  "growCrop": {
    "c1": "I pomodori vanno bene nella tua zona con un po' di pianificazione. Semina al chiuso sei-otto settimane prima dell'ultima gelata, abituali all'esterno e trapianta quando le notti restano sopra i 50°F.",
    "c2": "I peperoni hanno bisogno di caldo per partire in zona temperata. Seminali presto al chiuso, aspetta che il terreno si scaldi per trapiantare e aspettati il raccolto principale a fine estate.",
    "c3": "La lattuga nella tua zona è una coltura primaverile e autunnale: va a seme col caldo estivo. Semina poco e spesso e dalle ombra pomeridiana per allungare la stagione.",
    "c4": "Gli spinaci si adattano alla tua zona nella metà fresca dell'anno. Semina a inizio primavera e di nuovo a fine estate per un taglio autunnale; seminati in piena estate vanno a seme.",
    "c5": "Il cavolo riccio è tra le colture più facili in zona temperata e resiste quasi tutto l'inverno. Semina a metà estate per raccogliere in autunno e inverno: le foglie si addolciscono dopo le prime gelate.",
    "c6": "I cavoli rendono meglio prima e dopo l'estate nella tua zona. Seminali al chiuso e trapiantali per un raccolto primaverile, o semina a metà estate per uno autunnale migliore, e proteggili con una rete dalla cavolaia.",
    "c7": "Le carote crescono bene nella tua zona con una semina a inizio primavera e un'altra a metà estate per radici autunnali. Dai loro terreno profondo e senza sassi e dirada le piantine, o avrai radici biforcute e stentate.",
    "c8": "L'aglio è una classica coltura temperata e vuole il tuo inverno. Pianta gli spicchi in autunno perché ricevano il freddo necessario a formare la testa, e raccogli quando le foglie basse ingialliscono a metà estate.",
    "c9": "I piselli amano l'avvio fresco della stagione. Semina appena il terreno è lavorabile, dai loro un sostegno e raccogli spesso: smettono di produrre col caldo.",
    "c10": "I fagioli sono una coltura estiva affidabile nella tua zona ma odiano il terreno freddo. Semina dopo l'ultima gelata, fai una seconda semina qualche settimana dopo e continua a raccogliere.",
    "c11": "Questa pianta sta bene in un'estate temperata una volta passato il freddo. Trapianta dopo l'ultima gelata in terreno ricco, annaffia alla base e non sulle foglie, e aspettati più di quanto pensavi.",
    "c12": "Le patate dolci non sono patate e vogliono una stagione calda, che la tua zona offre appena. Pianta talee radicate ben dopo l'ultima gelata a terreno caldo e raccogli prima della prima gelata autunnale.",
    "c13": "Le patate si adattano alla lunga primavera fresca della tua zona. Pianta i tuberi da seme un paio di settimane prima dell'ultima gelata, rincalzali alla crescita e raccogli le tardive quando il fogliame secca.",
    "c14": "Le fragole sono perenni nella tua zona e producono di più al secondo anno. Piantale in primavera o autunno, pacciama sotto i frutti per tenerli puliti e copri i colletti nelle settimane più fredde.",
    "c15": "Il basilico è il più delicato dell'orto temperato. Tienilo al chiuso finché le notti restano stabilmente sopra i 50°F, dagli il posto più soleggiato e cima le punte per ritardare la fioritura.",
    "c16": "La tua zona gli dà il freddo invernale necessario per fruttificare bene, cosa che le zone calde non possono. Pianta un albero a radice nuda a riposo, pota per aprire il centro e dirada un carico abbondante perché i rami lo reggano.",
    "c17": "I pomodori prosperano nelle zone calde ma servono annaffiature profonde costanti e pacciamatura per superare l'estate. Scegli varietà tolleranti al caldo come Solar Fire o Heatmaster.",
    "c18": "I peperoni sono tra i migliori ortaggi per le zone calde: amano il caldo e producono in abbondanza. Annaffia con costanza e goditi una stagione lunga e produttiva.",
    "c19": "Il basilico prospera al caldo e al sole, perfetto per la tua zona. Piantalo dopo l'ultima gelata in pieno sole e togli spesso i fiori per mantenere le foglie saporite.",
    "c20": "L'anguria è un'ottima scelta per le zone calde: il caldo accelera crescita e dolcezza. Dai molto spazio, annaffia a fondo ogni settimana e goditi un bel raccolto.",
    "c21": "L'okra è tra i migliori ortaggi per i climi caldi e cresce quasi da sola. Piantala in pieno sole e raccogli ogni 2 giorni in piena stagione.",
    "c22": "La melanzana ama il caldo e rende benissimo nelle zone calde. Mantieni il terreno sempre umido e goditi una stagione lunga e produttiva.",
    "c23": "Le patate dolci sono perfette per le zone calde: amano il caldo e producono molto nelle stagioni lunghe. Pianta le talee dopo l'ultima gelata e lascia spazio ai tralci.",
    "c24": "Il cavolo riccio è tra i migliori ortaggi per le zone fredde: migliora di sapore dopo il gelo. Piantalo a fine estate per un raccolto autunnale e di inizio inverno sempre più dolce.",
    "c25": "Gli spinaci prosperano nelle zone fredde e sono tra le prime colture di primavera. Tollerano gelate leggere e danno foglie tenere col fresco.",
    "c26": "I piselli sono perfetti per le zone fredde: amano il fresco e si seminano appena il terreno è lavorabile in primavera. Aspettati un buon raccolto prima del caldo.",
    "c27": "Le patate si adattano bene alle zone fredde con stagioni lunghe e fresche. Pianta tuberi da seme certificati a inizio primavera e aspettati un raccolto generoso a fine estate.",
    "c28": "Le carote prosperano nei climi freschi e diventano dolcissime dopo gelate leggere. Seminale in terreno profondo, soffice e senza sassi per radici dritte e grandi.",
    "c29": "I broccoli sono ideali per le zone fredde: amano le temperature fresche e rendono meglio in primavera o autunno. Seminali presto al chiuso e trapiantali col fresco per un raccolto di prima qualità.",
  },
