    "carrotRustFly_name": "Mosca della carota",
    "carrotRustFly_description": "Una mosca le cui larve scavano gallerie color ruggine nelle carote e nelle radici di altre ombrellifere.",
    "codlingMoth_name": "Carpocapsa",
    "codlingMoth_description": "Il classico «verme della mela»: una falena le cui larve scavano gallerie fino al torsolo.",
    "europeanCornBorer_name": "Piralide del mais",
    "europeanCornBorer_description": "Una falena i cui bruchi penetrano negli steli e nelle pannocchie del mais e nei frutti del peperone.",
    "figBeetle_name": "Cetonia dei fichi",
