    "onionMaggot_description": "Le larve di una mosca che scavano gallerie nelle radici e nei bulbi della famiglia della cipolla.",
    "parsleyworm_name": "Bruco del prezzemolo",
    "parsleyworm_description": "Il vistoso bruco della farfalla macaone nera.",
    "peachTreeBorer_name": "Sesia del pesco",
    "peachTreeBorer_description": "Una falena dalle ali trasparenti le cui larve penetrano nella base del tronco degli alberi da frutto a nocciolo.",
    "pearPsylla_name": "Psilla del pero",
