    "strawberryBudWeevil_name": "Antonomo della fragola",
    "strawberryBudWeevil_description": "Il «tagliafragole»: un punteruolo che recide i boccioli fiorali per deporvi le uova.",
    "sweetPotatoWeevil_name": "Punteruolo della patata dolce",
    "sweetPotatoWeevil_description": "Un punteruolo simile a una formica le cui larve scavano gallerie nelle radici e nei tralci della patata dolce.",
    "wireworm_name": "Elateridi (ferretti)",
    "wireworm_description": "Le larve coriacee e filiformi dei coleotteri schiaccianoci, che vivono per anni nel terreno.",
    "aphids_sign": "Gruppi di minuscoli insetti verdi/neri sui germogli nuovi e sulla pagina inferiore delle foglie; residuo appiccicoso.",
