    "peachTreeBorer_sign": "Gommosi appiccicosa e escrementi simili a segatura che fuoriescono alla base del tronco.",
    "peachTreeBorer_damage": "Le larve cingono la parte bassa del tronco, indebolendo o uccidendo gli alberi giovani.",
    "pearPsylla_sign": "Melata appiccicosa, fumaggine nera e foglie arricciate che ingialliscono.",
    "pearPsylla_damage": "L'alimentazione e la melata anneriscono le foglie di fumaggine e possono diffondere il deperimento del pero.",
    "perseaMite_sign": "Macchie gialle e chiazze brune lungo le nervature, con fine ragnatela.",
    "perseaMite_damage": "L'alimentazione uccide il tessuto fogliare a chiazze, causando caduta delle foglie e frutti scottati dal sole.",
    "plumCurculio_sign": "Cicatrici a forma di mezzaluna sui frutti giovani e caduta precoce dei frutti.",
    "plumCurculio_damage": "La deposizione delle uova lascia cicatrici a mezzaluna, e le larve fanno cadere i frutti precocemente.",
    "pomegranateButterfly_sign": "Fori nella buccia e frutti svuotati che marciscono.",
    "pomegranateButterfly_damage": "I bruchi scavano gallerie dentro il frutto, causando un marciume che resta nascosto fino al raccolto.",
    "rootKnotNematode_sign": "Piante stentate e appassite con galle nodose lungo le radici.",
    "rootKnotNematode_damage": "Le radici con galle non riescono ad assorbire acqua e nutrienti, quindi le piante appassiscono e producono poco.",
    "spittlebug_sign": "Grumi di «sputo» schiumoso sugli steli, con una ninfa nascosta all'interno.",
    "spittlebug_damage": "Un attacco intenso può frenare la nuova crescita, ma la maggior parte delle piante lo sopporta senza problemi.",
    "spottedWingDrosophila_sign": "Bacche mature molli, infossate e che collassano in fretta, con minuscole larve all'interno.",
    "spottedWingDrosophila_damage": "Le larve si nutrono all'interno delle bacche, che diventano molli e spappolate pochi giorni dopo la maturazione.",
    "stinkBug_sign": "Macchie opache e infossate sui frutti e cimici a forma di scudo sulle piante.",
    "stinkBug_damage": "L'alimentazione lascia macchie dure e suberose e fossette che deformano frutti e baccelli.",
    "strawberryBudWeevil_sign": "Boccioli fiorali recisi che penzolano dallo stelo.",
    "strawberryBudWeevil_damage": "Recide i boccioli non ancora aperti, riducendo il numero di fragole che la pianta può produrre.",
    "sweetPotatoWeevil_sign": "Radici con gallerie dal sapore amaro e sottili coleotteri bluastri.",
    "sweetPotatoWeevil_damage": "Le gallerie rendono le radici amare e immangiabili, e il danno continua durante la conservazione.",
    "wireworm_sign": "Fori stretti in radici e tuberi, con sottili larve arancioni nel terreno.",
    "wireworm_damage": "Scavano fori netti in tuberi, radici e semi, aprendo la strada al marciume.",
    "aphids_fix": "Eliminali con un getto d'acqua, poi tratta con sapone insetticida. Le coccinelle aiutano a lungo termine.",
    "aphids_prevent": "Attira coccinelle e crisope, evita l'eccesso di azoto (favorisce la crescita tenera che adorano) e controlla i nuovi germogli ogni settimana.",
    "tomatoHornworms_fix": "Raccoglile a mano al tramonto (brillano sotto la luce UV). Spray a base di Bt per infestazioni forti.",
    "tomatoHornworms_prevent": "Vanga il terreno in autunno per distruggere le pupe, pianta aneto o tagete per attirare le vespe parassite e controlla al tramonto.",
    "squashBugs_fix": "Schiaccia presto le uova, rimuovi gli adulti a mano e tieni le aiuole libere da residui.",
    "squashBugs_prevent": "Ruota ogni anno le cucurbitacee, elimina i residui in cui svernano, usa teli protettivi fino alla fioritura e distruggi presto le ovature.",
    "cabbageWorms_fix": "Usa teli protettivi a inizio stagione, spray a base di Bt e raccogli i bruchi a mano.",
    "cabbageWorms_prevent": "Copri le brassicacee con rete fine così le farfalle non depongono le uova, consocia erbe aromatiche e strofina via le uova dal lato inferiore delle foglie.",
    "slugsSnails_fix": "Raccoglili a mano di notte, usa trappole alla birra o circonda le aiuole con nastro di rame.",
    "slugsSnails_prevent": "Annaffia al mattino così il terreno si asciuga entro sera, rimuovi i nascondigli come assi e pacciamatura spessa, e metti barriere di rame o trappole alla birra.",
    "spiderMites_fix": "Aumenta l'umidità, lava il lato inferiore delle foglie con un getto d'acqua e tratta con sapone insetticida o neem.",
